11	#[derive(Debug, Default)]
12	pub struct LockedRequirements {
13	    /// The pinned versions from the lockfile.
14	    pub preferences: Vec<Preference>,
15	    /// The pinned Git SHAs from the lockfile.
16	    pub git: Vec<ResolvedRepositoryReference>,
17	}
18	
19	impl LockedRequirements {
20	    /// Create a [`LockedRequirements`] from a list of preferences.
21	    pub fn from_preferences(preferences: Vec<Preference>) -> Self {
22	        Self {
23	            preferences,
24	            ..Self::default()
25	        }
26	    }
27	}
