29	/// Load the preferred requirements from an existing `requirements.txt`, applying the upgrade strategy.
30	pub async fn read_requirements_txt(
31	    output_file: &Path,
32	    upgrade: &Upgrade,
33	) -> Result<Vec<Preference>> {
34	    // As an optimization, skip reading the lockfile is we're upgrading all packages anyway.
35	    if upgrade.is_all() {
36	        return Ok(Vec::new());
37	    }
38	
39	    // Parse the requirements from the lockfile.
40	    let requirements_txt = RequirementsTxt::parse(output_file, &*CWD).await?;
41	
42	    // Map each entry in the lockfile to a preference.
43	    let preferences = requirements_txt
44	        .requirements
45	        .into_iter()
46	        .map(Preference::from_entry)
47	        .filter_map(Result::transpose)
48	        .collect::<Result<Vec<_>, PreferenceError>>()?;
49	
50	    // Apply the upgrade strategy to the requirements.
51	    Ok(match upgrade {
52	        // Respect all pinned versions from the existing lockfile.
53	        Upgrade::None => preferences,
54	        // Ignore all pinned versions from the existing lockfile.
55	        Upgrade::All => vec![],
56	        // Ignore pinned versions for the specified packages.
57	        Upgrade::Packages(packages) => preferences
58	            .into_iter()
59	            .filter(|preference| !packages.contains_key(preference.name()))
60	            .collect(),
61	    })
62	}
63	
64	/// Load the preferred requirements from an existing lockfile, applying the upgrade strategy.
65	pub fn read_lock_requirements(
66	    lock: &Lock,
67	    install_path: &Path,
68	    upgrade: &Upgrade,
69	) -> Result<LockedRequirements, LockError> {
70	    // As an optimization, skip iterating over the lockfile is we're upgrading all packages anyway.
71	    if upgrade.is_all() {
72	        return Ok(LockedRequirements::default());
73	    }
74	
75	    let mut preferences = Vec::new();
76	    let mut git = Vec::new();
77	
78	    for package in lock.packages() {
79	        // Skip the distribution if it's not included in the upgrade strategy.
80	        if upgrade.contains(package.name()) {
81	            continue;
82	        }
83	
84	        // Map each entry in the lockfile to a preference.
85	        if let Some(preference) = Preference::from_lock(package, install_path)? {
86	            preferences.push(preference);
87	        }
88	
89	        // Map each entry in the lockfile to a Git SHA.
90	        if let Some(git_ref) = package.as_git_ref()? {
91	            git.push(git_ref);
92	        }
93	    }
94	
95	    Ok(LockedRequirements { preferences, git })
96	}
97	
98	/// Load the preferred requirements from an existing `pylock.toml` file, applying the upgrade strategy.
99	pub async fn read_pylock_toml_requirements(
100	    output_file: &Path,
101	    upgrade: &Upgrade,
102	) -> Result<LockedRequirements, PylockTomlErrorKind> {
103	    // As an optimization, skip iterating over the lockfile is we're upgrading all packages anyway.
104	    if upgrade.is_all() {
105	        return Ok(LockedRequirements::default());
106	    }
107	
108	    // Read the `pylock.toml` from disk, and deserialize it from TOML.
109	    let content = fs_err::tokio::read_to_string(&output_file).await?;
110	    let lock = toml::from_str::<PylockToml>(&content)?;
111	
112	    let mut preferences = Vec::new();
113	    let mut git = Vec::new();
114	
115	    for package in &lock.packages {
116	        // Skip the distribution if it's not included in the upgrade strategy.
117	        if upgrade.contains(&package.name) {
118	            continue;
119	        }
120	
121	        // Map each entry in the lockfile to a preference.
122	        if let Some(preference) = Preference::from_pylock_toml(package)? {
123	            preferences.push(preference);
124	        }
125	
126	        // Map each entry in the lockfile to a Git SHA.
127	        if let Some(git_ref) = package.as_git_ref() {
128	            git.push(git_ref);
129	        }
130	    }
131	
132	    Ok(LockedRequirements { preferences, git })
133	}
